#!/usr/bin/env node

/**
 * Aggregates per-package CHANGELOG.md files (generated by changesets)
 * into a single unified CHANGELOG.md at the repo root, and normalizes
 * the per-package changelogs themselves.
 *
 * Since all packages are in a changesets "fixed" group and share the
 * same version number, the root changelog presents one deduplicated
 * entry list per release, annotated with the packages each change
 * touched.
 *
 * Responsibilities (all idempotent):
 * - Strip legacy `abc1234: ` commit-SHA prefixes from entries (the
 *   custom .changeset/changelog.cjs generator no longer emits them,
 *   but historical entries carry them).
 * - Drop "Updated dependencies" noise from historical entries.
 * - Maintain scripts/release-dates.json: any version discovered without
 *   a recorded date is stamped with today's date (this script runs
 *   inside `pnpm version:bump`, immediately after `changeset version`,
 *   so "today" is the version-bump date).
 * - Rewrite per-package CHANGELOG.md files with cleaned entries and
 *   dated version headings: `## 1.2.3 (2026-07-10)`.
 * - Regenerate the root CHANGELOG.md grouped release -> section ->
 *   entries, each entry annotated with the packages that carried it.
 *
 * Run automatically via: pnpm version:bump
 * Run manually via:      node scripts/aggregate-changelog.js
 */

const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');

const PACKAGES = [
  'packages/components',
  'packages/tokens',
  'packages/icons',
  'packages/react',
  'packages/vue',
  'packages/angular',
  'packages/cli',
  'packages/vscode',
  'packages/workbench',
  'packages/docs',
];

const SECTION_ORDER = ['Major Changes', 'Minor Changes', 'Patch Changes'];

/** Strip a legacy `abc1234: ` commit prefix from an entry, if present. */
function stripHashPrefix(item) {
  return item.replace(/^[a-f0-9]{7,40}: /, '');
}

/**
 * Normalize an entry whose summary itself starts with a markdown list
 * ("- - First point\n  - Second point"): promote the first sub-item to
 * the entry's lead line so it doesn't render as a double bullet.
 */
function promoteLeadBullet(item) {
  if (!item.startsWith('- ')) return item;
  return item.slice(2);
}

/** Check if an item is an "Updated dependencies" entry (internal dep noise). */
function isDepUpdate(item) {
  return /^Updated dependencies/i.test(item.trim());
}

/** Dedup key: entry text normalized for whitespace differences. */
function entryKey(item) {
  return item.replace(/\s+/g, ' ').trim();
}

/**
 * Parse a changesets-generated CHANGELOG.md into structured releases.
 * Each release has a version, optional date, and sections keyed by
 * section name ("Minor Changes", ...) containing entry strings (which
 * may span multiple lines via indented continuations).
 *
 * Accepts both legacy headings (`## 1.2.3`, `## 1.2.3 - date`) and the
 * normalized form (`## 1.2.3 (2026-07-10)`).
 */
function parseChangelog(raw) {
  const releases = [];
  const title = raw.split('\n')[0].replace(/^#\s*/, '').trim();
  const versionBlocks = raw.split(/^## /m).slice(1);

  for (const block of versionBlocks) {
    const lines = block.split('\n');
    const heading = lines[0].trim();
    const match = heading.match(
      /^(\d+\.\d+\.\d+(?:-[^\s]+)?)\s*(?:[-–—]\s*(.+)|\((\d{4}-\d{2}-\d{2})\))?$/,
    );
    if (!match) continue;

    const version = match[1];
    const date = (match[3] || match[2] || '').trim();
    const sections = {};
    let currentSection = null;
    let currentItem = null;

    for (let i = 1; i < lines.length; i++) {
      const line = lines[i];

      const sectionMatch = line.match(/^### (.+)/);
      if (sectionMatch) {
        currentSection = sectionMatch[1].trim();
        if (!sections[currentSection]) sections[currentSection] = [];
        currentItem = null;
        continue;
      }

      if (!currentSection) continue;

      const itemMatch = line.match(/^- (.+)/);
      if (itemMatch) {
        currentItem = itemMatch[1];
        sections[currentSection].push(currentItem);
        continue;
      }

      // Continuation line (indented): belongs to the current item
      if (currentItem !== null && line.match(/^\s+/) && line.trim()) {
        const idx = sections[currentSection].length - 1;
        sections[currentSection][idx] += '\n' + line;
      }
    }

    releases.push({ version, date, sections });
  }

  return { title, releases };
}

/** Clean a release's sections: strip SHAs, drop dep noise, drop empty sections. */
function cleanSections(sections) {
  const cleaned = {};
  for (const [section, items] of Object.entries(sections)) {
    const kept = items
      .filter((item) => !isDepUpdate(item))
      .map(stripHashPrefix)
      .map(promoteLeadBullet);
    if (kept.length > 0) cleaned[section] = kept;
  }
  return cleaned;
}

/** Sort section names in the preferred order, unknown sections last. */
function orderSections(names) {
  return [...names].sort((a, b) => {
    const ai = SECTION_ORDER.indexOf(a);
    const bi = SECTION_ORDER.indexOf(b);
    return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
  });
}

/** Compare semver strings descending. */
function compareVersionsDesc(a, b) {
  const ap = a.split(/[.-]/).map((part) => Number(part) || 0);
  const bp = b.split(/[.-]/).map((part) => Number(part) || 0);
  for (let i = 0; i < 3; i++) {
    if ((bp[i] || 0) !== (ap[i] || 0)) return (bp[i] || 0) - (ap[i] || 0);
  }
  return 0;
}

/** Serialize releases back into a per-package CHANGELOG.md. */
function renderPackageChangelog(title, releases, dates) {
  const lines = [`# ${title}`, ''];

  for (const release of releases) {
    const date = dates[release.version];
    lines.push(date ? `## ${release.version} (${date})` : `## ${release.version}`, '');

    for (const section of orderSections(Object.keys(release.sections))) {
      lines.push(`### ${section}`, '');
      for (const item of release.sections[section]) {
        lines.push(`- ${item}`);
      }
      lines.push('');
    }
  }

  return (
    lines
      .join('\n')
      .replace(/\n{3,}/g, '\n\n')
      .trimEnd() + '\n'
  );
}

/** Short display name for a package directory ("packages/components" -> "components"). */
function shortPackageName(pkgDir) {
  return pkgDir.split('/').pop();
}

/**
 * Aggregate parsed per-package changelogs into the root changelog model.
 * Returns a Map of version -> { sections: { name -> [{text, packages}] } }.
 */
function aggregateReleases(perPackage) {
  const versionMap = new Map();

  for (const { pkg, releases } of perPackage) {
    for (const release of releases) {
      if (!versionMap.has(release.version)) {
        versionMap.set(release.version, { sections: {} });
      }
      const merged = versionMap.get(release.version);

      for (const [section, items] of Object.entries(release.sections)) {
        if (!merged.sections[section]) merged.sections[section] = [];

        for (const item of items) {
          const key = entryKey(item);
          const existing = merged.sections[section].find((entry) => entry.key === key);
          if (existing) {
            if (!existing.packages.includes(pkg)) existing.packages.push(pkg);
          } else {
            merged.sections[section].push({ key, text: item, packages: [pkg] });
          }
        }
      }
    }
  }

  // Deduplicate across sections within a version: keep an entry in the
  // highest-priority section only (Major > Minor > Patch).
  for (const { sections } of versionMap.values()) {
    const seen = new Set();
    for (const section of orderSections(Object.keys(sections))) {
      sections[section] = sections[section].filter((entry) => {
        if (seen.has(entry.key)) return false;
        seen.add(entry.key);
        return true;
      });
      if (sections[section].length === 0) delete sections[section];
    }
  }

  return versionMap;
}

/** Render the root CHANGELOG.md. */
function renderRootChangelog(versionMap, dates, totalPackages) {
  const lines = ['# Cobalt Design System', ''];
  const sortedVersions = [...versionMap.keys()].sort(compareVersionsDesc);

  for (const version of sortedVersions) {
    const { sections } = versionMap.get(version);
    const date = dates[version];
    lines.push(date ? `## ${version} (${date})` : `## ${version}`, '');

    let hasContent = false;
    for (const section of orderSections(Object.keys(sections))) {
      const entries = sections[section];
      if (entries.length === 0) continue;
      hasContent = true;
      lines.push(`### ${section}`, '');
      for (const entry of entries) {
        // Annotate with touched packages only when the change is clearly
        // scoped (half the packages or fewer) — release-wide changes
        // annotated with almost every package name are just noise.
        const annotate = entry.packages.length > 0 && entry.packages.length <= totalPackages / 2;
        const names = entry.packages.map(shortPackageName).join(', ');
        const [first, ...rest] = entry.text.split('\n');
        const annotated = annotate ? `${first} _(${names})_` : first;
        lines.push(`- ${annotated}`, ...rest);
      }
      lines.push('');
    }

    if (!hasContent) {
      lines.push('_No notable changes._', '');
    }
  }

  return (
    lines
      .join('\n')
      .replace(/\n{3,}/g, '\n\n')
      .trimEnd() + '\n'
  );
}

/**
 * Main entry: reads per-package changelogs, updates the date registry,
 * rewrites normalized per-package changelogs, writes the root changelog.
 */
function aggregate({
  rootDir = root,
  packages = PACKAGES,
  today = new Date().toISOString().slice(0, 10),
  write = true,
} = {}) {
  const datesPath = path.join(rootDir, 'scripts', 'release-dates.json');
  const dates = fs.existsSync(datesPath) ? JSON.parse(fs.readFileSync(datesPath, 'utf-8')) : {};

  const perPackage = [];
  for (const pkg of packages) {
    const changelogPath = path.join(rootDir, pkg, 'CHANGELOG.md');
    if (!fs.existsSync(changelogPath)) continue;
    const raw = fs.readFileSync(changelogPath, 'utf-8');
    const { title, releases } = parseChangelog(raw);

    for (const release of releases) {
      release.sections = cleanSections(release.sections);
      // Legacy inline heading dates win over "today" for backfill accuracy.
      if (release.date && !dates[release.version]) {
        dates[release.version] = release.date;
      }
    }

    perPackage.push({ pkg: shortPackageName(pkg), title, releases, changelogPath });
  }

  // Stamp any version that still has no recorded date with today.
  for (const { releases } of perPackage) {
    for (const release of releases) {
      if (!dates[release.version]) dates[release.version] = today;
    }
  }

  const versionMap = aggregateReleases(perPackage);
  const rootChangelog = renderRootChangelog(versionMap, dates, perPackage.length);

  if (write) {
    for (const { title, releases, changelogPath } of perPackage) {
      fs.writeFileSync(changelogPath, renderPackageChangelog(title, releases, dates), 'utf-8');
    }
    fs.writeFileSync(datesPath, JSON.stringify(dates, null, 2) + '\n', 'utf-8');
    fs.writeFileSync(path.join(rootDir, 'CHANGELOG.md'), rootChangelog, 'utf-8');
  }

  return { dates, versionMap, rootChangelog, packageCount: perPackage.length };
}

module.exports = {
  parseChangelog,
  cleanSections,
  aggregateReleases,
  renderPackageChangelog,
  renderRootChangelog,
  aggregate,
};

if (require.main === module) {
  const result = aggregate();
  console.log(`Wrote unified changelog to ${path.join(root, 'CHANGELOG.md')}`);
  console.log(
    `  ${result.versionMap.size} version(s) aggregated from ${result.packageCount} package(s)`,
  );
}
